C<pre><code>void bubblesort(int *p , int n){
    int i,j;
    for(i=n-1;i&gt;0;i--){
        for(j=0;j&lt;i;j++){
            if(*(p+j)&gt;*(p+j+1)){
                int temp=*(p+j);
                *(p+j)=*(p+j+1);
                *(p+j+1)=temp;  
                n=j+1;  //记录最后一次交换的位置
            }
        }
    }
}
</code></pre>

