C<pre><code>void insertionsort(int *p , int n){
    if(n&gt;1){
        insertionsort(p,n-1);
        int index=n-1;
        int temp=*(p+n-1);
        for(int i=0;i&lt;n-1;i++){
            if(*(p+i)&gt;*(p+index)){
                index=i;
                break;
            }
        }
        for(int j=n-1;j&gt;index;j--){
            *(p+j)=*(p+j-1);
        }
        *(p+index)=temp;
    }
}
</code></pre>

C<pre><code>void insertionsort(int *p , int n){
    if(n&gt;1){
        insertionsort(p,n-1);
        int index=n-1;
        int temp=*(p+n-1);
        for(int i=n-1;i&gt;0 &amp;&amp; *(p+i-1)&gt;temp;i--){
            *(p+i)=*(p+i-1);
            index=i-1;
        }
        *(p+index)=temp;
    }
}
</code></pre>

C<pre><code>void quicksort(int *p , int start ,int end){
    if(start&lt;end){
        int temp=*(p+end);   //分区元素为最后一个元素
        int i=end-1;
        for(int k=end-1;k&gt;start-1;k--){
            if(*(p+k)&gt;temp){
                int a=*(p+i);
                *(p+i)=*(p+k);
                *(p+k)=a;
                i--;
            }
        }
        *(p+end)=*(p+i+1);
        *(p+i+1)=temp;
        quicksort(p,start,i);
        quicksort(p,i+2,end);
    }
}
</code></pre> <p>Notice!</p> <p>也可以从开头、结尾和中间的三个元素中选择一个中等的</p>

